   [167]={next_id=168, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="狮刃痛苦地闭上眼睛，紧握拳头的手微微发颤。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_402.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [168]={next_id=169, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="我以为……只要我把所有罪责都扛下来了，他们就会平安无事。", msg_color="", msg_size=0, talker="狮刃", audio="", img="arts/ui/bg/story/storybg_402.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "3102", 0, 0, 49, 175.5}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
